INSERT OR REPLACE INTO service_areas (id, name, slug, headline, description, landmarks, keywords, popular_services, status, display_order, created_at, updated_at) VALUES ('8Ll3TfebVgRVZ33Iwwid', 'Uttara', 'uttara', 'Euro Spa Center serves clients in Uttara, Dhaka with professional massage and wellness treatments in a clean and comfortable environment.', 'Euro Spa Center serves clients from Uttara and nearby areas of Dhaka from our spa center at 73 Road No. 6, Banani. Our Banani location offers professional Swedish Massage, Deep Tissue Massage, Aromatherapy, Hot Stone Massage, and other wellness treatments for clients seeking relaxation and wellness services. The center provides a clean, comfortable environment and daily appointments from 10:00 AM to 10:00 PM.', '[]', '["spa and massage in Uttara"]', '[]', 'active', 5, '2026-09-08T08:28:17.921Z', '2026-09-08T08:28:16.022Z');
INSERT OR REPLACE INTO service_areas (id, name, slug, headline, description, landmarks, keywords, popular_services, status, display_order, created_at, updated_at) VALUES ('CdqZcHoNpX3yMzZ4FGyL', 'Banani', 'banani', 'Euro Spa Center at 73 Road No. 6, Banani, Dhaka offers professional massage and wellness treatments in a clean, comfortable environment.', 'Euro Spa Center is located at 73 Road No. 6, Banani, Dhaka, serving clients from Banani and nearby areas. Our Banani center offers professional Swedish Massage, Deep Tissue Massage, Aromatherapy, Hot Stone Massage, and other wellness treatments in a clean and comfortable environment. Guests can easily contact us for appointments and visit during our daily operating hours from 10:00 AM to 10:00 PM. Whether you are looking for relaxation, muscle tension relief, or a wellness treatment, our Banani location provides a convenient spa experience in Dhaka.', '[]', '["Spa in Banani"]', '[]', 'active', 1, '2026-09-08T08:18:33.579Z', '2026-09-08T08:18:30.251Z');
INSERT OR REPLACE INTO service_areas (id, name, slug, headline, description, landmarks, keywords, popular_services, status, display_order, created_at, updated_at) VALUES ('Ejg0pqEpLnKUVl0P5fVJ', 'Gulshan', 'gulshan', 'Euro Spa Center serves clients in Gulshan, Dhaka with professional massage and wellness treatments in a clean, comfortable environment.', 'Euro Spa Center serves clients from Gulshan and nearby areas of Dhaka from our spa center at 73 Road No. 6, Banani. Our location is convenient for Gulshan residents, professionals, and visitors seeking a relaxing wellness experience. We offer Swedish Massage, Deep Tissue Massage, Aromatherapy, Hot Stone Massage, and other professional wellness treatments in a clean and comfortable environment. Contact Euro Spa Center to book an appointment and enjoy our daily service hours from 10:00 AM to 10:00 PM.', '[]', '["spa and massage in Gulshan"]', '[]', 'active', 2, '2026-09-08T08:22:59.990Z', '2026-09-08T08:22:56.573Z');
INSERT OR REPLACE INTO service_areas (id, name, slug, headline, description, landmarks, keywords, popular_services, status, display_order, created_at, updated_at) VALUES ('asYzU0BjqtpWdaHir7wB', 'Dhanmondi', 'dhanmondi', 'Euro Spa Center serves clients in Dhanmondi, Dhaka with professional massage and wellness treatments in a clean and comfortable environment.', 'Euro Spa Center serves clients from Dhanmondi and nearby areas of Dhaka from our spa center at 73 Road No. 6, Banani. Our convenient Banani location provides access to professional Swedish Massage, Deep Tissue Massage, Aromatherapy, Hot Stone Massage, and other wellness treatments for Dhanmondi residents and visitors. We provide a clean, comfortable, and relaxing environment for clients seeking professional spa and wellness services. Contact Euro Spa Center to book an appointment, with services available daily from 10:00 AM to 10:00 PM.', '[]', '["spa and massage in Dhanmondi"]', '[]', 'active', 4, '2026-09-08T08:27:38.752Z', '2026-09-08T08:27:36.858Z');
INSERT OR REPLACE INTO service_areas (id, name, slug, headline, description, landmarks, keywords, popular_services, status, display_order, created_at, updated_at) VALUES ('l6U7ITKiEDgIqzvJWzoq', 'Dhaka', 'dhaka', 'Euro Spa Center offers professional spa, massage, and wellness treatments for clients across Dhaka from our Banani location.', 'Euro Spa Center is a professional spa and wellness center located at 73 Road No. 6, Banani, Dhaka 1213. We welcome clients from across Dhaka looking for professional Swedish Massage, Deep Tissue Massage, Aromatherapy, Hot Stone Massage, Body Scrub, and other wellness treatments. Our Banani center provides a clean, comfortable, and relaxing environment, with appointments available daily from 10:00 AM to 10:00 PM. Contact Euro Spa Center to book a session or learn more about our available treatments.', '[]', '["spa and massage in Dhaka"]', '[]', 'active', 6, '2026-09-08T08:29:05.697Z', '2026-09-08T08:29:03.797Z');

-- Table: faqs (7 records)
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-1', 'Where is Euro Spa Center located in Banani?', 'We are conveniently located at 73 Road No. 6, Banani, Dhaka 1213, Bangladesh. We are easily accessible from Gulshan, Baridhara, and Mohakhali with dedicated valet and private entrance parking.', 'Location & Arrival', 'active', 1, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-2', 'Do I need an advance appointment or do you accept walk-ins?', 'While we welcome walk-ins based on therapist availability, we strongly recommend booking in advance via our website, direct phone call (01842-658423), or WhatsApp to ensure your preferred suite and therapist are ready upon arrival.', 'Bookings', 'active', 2, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-3', 'What types of massage therapy do you offer?', 'We specialize in Dry Massage, Relaxing Oil Massage, Swedish Massage, Deep Tissue Therapy, Aromatherapy, Hot Stone Massage, Four-Hand Synchronized Massage, and specialized Herbal Body Scrubs.', 'Services', 'active', 3, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-4', 'What hygiene and sanitization standards do you follow?', 'Cleanliness is our highest priority. All treatment suites undergo medical-grade sanitization between clients. We use 100% fresh, single-use sterilized linen, disposable slippers, and hypoallergenic organic oils.', 'Hygiene & Safety', 'active', 4, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-5', 'Are private showers and changing rooms available?', 'Yes. Every VIP therapy suite includes a private hot-water rain shower, dressing mirror, clean towels, and premium organic body wash and shampoo.', 'Facilities', 'active', 5, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-6', 'What are your daily operating hours?', 'Euro Spa Center is open 7 days a week, Monday through Sunday, from 10:00 AM to 10:00 PM, including most public holidays.', 'General', 'active', 6, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, status, sort_order, created_at, updated_at) VALUES ('faq-7', 'What payment methods do you accept?', 'We accept Cash (BDT), bKash, Nagad, and all major Credit and Debit Cards (Visa, Mastercard, American Express).', 'Pricing & Payment', 'active', 7, '2026-09-08T17:51:33.584Z', '2026-09-08T17:51:33.584Z');

-- Table: google_business_sync (1 records)
INSERT OR REPLACE INTO google_business_sync (id, status, sync_summary, last_sync_at, updated_at) VALUES ('euro_spa_center', 'idle', '{"locationId":"ChIJBXYo6tfHVTcR1ZOGYIsTHt4","reviewsCount":48,"rating":4.9,"reviews":[{"rating":5,"serviceUsed":"Full Body Massage","id":"rev-1","name":"Rifat Ahmed","date":"3 days ago","reviewText":"Very relaxing environment and professional staff. Highly recommended!","avatar":"https://lh3.googleusercontent.com/a/default-user","verified":true},{"reviewText":"One of the best spa experiences in Banani. Will visit again!","serviceUsed":"Swedish Massage","avatar":"https://lh3.googleusercontent.com/a/default-user","verified":true,"rating":5,"id":"rev-2","date":"1 week ago","name":"Mahima Islam"},{"verified":true,"serviceUsed":"Deep Tissue Massage","name":"Tanzid Hasan","date":"2 weeks ago","avatar":"https://lh3.googleusercontent.com/a/default-user","id":"rev-3","rating":5,"reviewText":"Clean, peaceful and very professional service. Loved it!"},{"serviceUsed":"Swedish Massage","avatar":"https://lh3.googleusercontent.com/a/default-user","name":"Sarah Jenkins","date":"3 weeks ago","verified":true,"rating":5,"id":"rev-4","reviewText":"Living in Gulshan/Banani, I was searching for an immaculate, truly tranquil spa. The Swedish massage was world-class. Pristine sheets and calming ambient music."},{"name":"Farhan Kabir","date":"1 month ago","avatar":"https://lh3.googleusercontent.com/a/default-user","reviewText":"Booked a 90-minute Hot Stone massage after a hectic business trip. The warmth of the stones relieved weeks of stiffness. 100% worth every taka.","serviceUsed":"Hot Stone Massage","verified":true,"rating":5,"id":"rev-5"},{"avatar":"https://lh3.googleusercontent.com/a/default-user","serviceUsed":"Aromatherapy Massage","verified":true,"date":"1 month ago","name":"Nusrat Jahan","reviewText":"The hygiene standards are exceptional! Private washroom, disposable slippers, and courteous reception. The aromatherapy oils smelled celestial.","id":"rev-6","rating":5},{"reviewText":"Great to have Euro Spa Center on Road 6 in Banani with proper certified therapists. Very convenient booking via WhatsApp and prompt confirmation.","avatar":"https://lh3.googleusercontent.com/a/default-user","date":"1 month ago","name":"Adnan Chowdhury","verified":true,"id":"rev-7","rating":5,"serviceUsed":"Deep Tissue Massage"},{"reviewText":"The Thai Herbal Compress gave me immediate relief from lower back ache. Beautiful decor with warm soothing lighting. Felt deeply revitalized!","id":"rev-8","date":"2 months ago","rating":5,"name":"Sabrina Rahman","avatar":"https://lh3.googleusercontent.com/a/default-user","verified":true,"serviceUsed":"Thai Herbal Compress Therapy"},{"verified":true,"reviewText":"Super clean rooms and complete privacy on Road 6 Banani. Loved the herbal tea served right after the session. Highly recommended!","avatar":"https://lh3.googleusercontent.com/a/default-user","id":"rev-9","rating":5,"serviceUsed":"Full Body Massage","date":"2 months ago","name":"Kazi Asif"},{"name":"Tasnim Anjum","date":"2 months ago","id":"rev-10","avatar":"https://lh3.googleusercontent.com/a/default-user","rating":5,"verified":true,"reviewText":"My mom and I booked a duo session for Swedish massage. The therapists were respectful, gentle, and very attentive to our comfort levels.","serviceUsed":"Swedish Massage"},{"verified":true,"avatar":"https://lh3.googleusercontent.com/a/default-user","reviewText":"Convenient location on Road 6, Banani. Staff escorted me inside promptly. Excellent massage and peaceful atmosphere.","date":"3 months ago","name":"Zubair Khan","id":"rev-11","rating":5,"serviceUsed":"Full Body Massage"},{"date":"3 months ago","name":"Sadia Parveen","id":"rev-12","rating":5,"verified":true,"serviceUsed":"Aromatherapy Massage","avatar":"https://lh3.googleusercontent.com/a/default-user","reviewText":"A true oasis in the middle of Banani. You forget the city noise the minute you step inside Euro Spa Center. The soothing scents are therapeutic."},{"id":"rev-13","date":"3 months ago","name":"Shahriar Hossain","serviceUsed":"Deep Tissue Massage","avatar":"https://lh3.googleusercontent.com/a/default-user","rating":5,"reviewText":"The deep tissue pressure was dialed in precisely. My desk-job shoulder tension completely melted away. Will definitely be a regular here.","verified":true},{"id":"rev-14","rating":5,"verified":true,"reviewText":"The warm foot reflexology scrub is heavenly! Left my feet feeling baby soft and walking felt lighter instantly.","avatar":"https://lh3.googleusercontent.com/a/default-user","serviceUsed":"Foot Reflexology & Botanical Scrub","date":"4 months ago","name":"Ayesha Siddiqua"},{"reviewText":"Booked an evening appointment around 7:00 PM. Welcoming reception, pristine towels, and pure professionalism throughout.","verified":true,"id":"rev-15","rating":5,"serviceUsed":"Full Body Massage","date":"4 months ago","avatar":"https://lh3.googleusercontent.com/a/default-user","name":"Imran Haque"},{"verified":true,"rating":5,"avatar":"https://lh3.googleusercontent.com/a/default-user","id":"rev-16","reviewText":"One of the best spa experiences in Banani, hands down. The heated massage beds make all the difference in relaxing muscles.","serviceUsed":"Swedish Massage","date":"4 months ago","name":"Nabila Karim"},{"rating":5,"id":"rev-17","reviewText":"Great customer care, courteous team, and clean private shower room. 5 stars for Euro Spa Center without hesitation.","name":"Mohammad Tareq","date":"5 months ago","serviceUsed":"Hot Stone Massage","avatar":"https://lh3.googleusercontent.com/a/default-user","verified":true},{"id":"rev-18","reviewText":"The hot stone therapy was soothing and magical. The therapists are certified and observe strict hygienic protocols.","rating":5,"date":"5 months ago","name":"Samira Akhtar","serviceUsed":"Hot Stone Massage","verified":true,"avatar":"https://lh3.googleusercontent.com/a/default-user"},{"rating":5,"id":"rev-19","name":"Arifur Rahman","date":"5 months ago","serviceUsed":"Full Body Massage","verified":true,"avatar":"https://lh3.googleusercontent.com/a/default-user","reviewText":"Convenient location on 73 Road 6, Banani. The rooms are spotless, tranquil, and comfortable."},{"avatar":"https://lh3.googleusercontent.com/a/default-user","verified":true,"id":"rev-20","serviceUsed":"Aromatherapy Massage","reviewText":"Remarkable attention to detail from the warm reception to the lavender wipe. Truly a relaxing haven in Banani.","name":"Mehnaz Latif","date":"6 months ago","rating":5},{"reviewText":"Visited twice already this month. Consistent quality, warm therapists, and prompt booking via WhatsApp.","verified":true,"rating":5,"avatar":"https://lh3.googleusercontent.com/a/default-user","id":"rev-21","date":"6 months ago","name":"Tanvir Ahmed","serviceUsed":"Deep Tissue Massage"}],"photos":[{"caption":"Welcoming therapists and courteous reception team at Euro Spa Center, Road 6, Banani.","title":"Euro Spa Center - Reception & Professional Team","fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606373/bf6dbe8d-a1bb-43c0-a36a-444b4488cbfa-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large","category":"Ambience","id":"user-photo-new-1","image":"/photos/new (1).jpg"},{"title":"Euro Spa Center - Therapy Preparation & Setup","category":"Facilities","caption":"Therapist prepares massage table at Euro Spa Center, creating a clean and calm ambiance.","fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606376/6c4d7161-b109-48b1-a18b-a0229c27e418-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large","image":"/photos/Image Aug.png","id":"user-photo-image-aug"},{"caption":"Relaxing two-bed room with white sheets and cyan runners in a purple ambient room.","title":"Euro Spa Center - Twin Therapy Suite","category":"Rooms","id":"user-photo-euroo","image":"/photos/euroo.png","fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606368/87e75dff-9ad8-4d19-9ff1-2226a94ec0c6-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large"},{"fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606369/08671ee0-a030-4fb2-98b6-ad2c4e69f7a2-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large","image":"/photos/euroo11.png","caption":"Tranquil massage room with cozy bed, ornate golden wallpaper, and patterned runner.","title":"Euro Spa Center - Ornate Golden VIP Suite","category":"Rooms","id":"user-photo-euroo11"},{"title":"Euro Spa Center - Twin Massage Beds & Seating","category":"Rooms","fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606372/b031a51d-f965-442f-91ed-7926b5d56992-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large","id":"user-photo-euros","caption":"Cozy spa room with two massage beds and armchairs at Euro Spa Center, Banani.","image":"/photos/euros.png"},{"id":"user-photo-3r333","category":"Rooms","caption":"Tranquil therapy room with comfortable bed, ideal for relaxation at Euro Spa Center.","image":"/photos/3r333.png","title":"Euro Spa Center - Serene Haven Spa Room","fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606371/e8f6836a-ddd0-4280-b380-fc92a093ddde-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large"},{"image":"https://lh3.googleusercontent.com/geougc/AF1QipPLNOXvJcErsUyF-6Jorv4EaoC6kDl3WaDnpL6W=w1200-h800-k-no","caption":"Euro Spa Center welcoming reception and serene wellness lounge on Road 6, Banani.","category":"Ambience","title":"Euro Spa Center Reception & Wellness Suite","id":"euro-gbp-reception"},{"id":"euro-gbp-room-1","category":"Rooms","title":"Private Therapy Room & Massage Bed","image":"https://lh3.googleusercontent.com/geougc/AF1QipPDGlDn8JiA8nC2xubXZCHfaV8c7sQkBsZr3iWL=w1200-h800-k-no","caption":"Spacious, peaceful private therapy room prepared for professional massage sessions."},{"caption":"Hygienic and comfortable environment designed for stress relief and deep relaxation.","id":"euro-gbp-room-2","image":"https://lh3.googleusercontent.com/geougc/AF1QipMfFcEWQskswYvq9pqc2q9710n5SDABSA0t7nuN=w1200-h800-k-no","title":"Relaxation Lounge & Therapy Suite","category":"Rooms"},{"image":"/photos/amenities.jpg","fallbackImage":"https://images.fresha.com/locations/location-profile-images/3078419/6606374/9265cde4-8bbf-40e3-84d0-dd5310acb293-EuroSpaCenter-BD-DhakaDivision-Dhaka-Gulshan-Fresha.jpg?class=venue-gallery-large","caption":"Hygienic facilities, modern amenities, and clean botanical essentials at Euro Spa Center.","id":"euro-gbp-facility","category":"Facilities","title":"Treatment Room & Wellness Amenities"}],"isGoogleConnected":true,"connectedAccountEmail":"mdalahi10000@gmail.com","businessName":"Euro Spa Center"}', '2026-09-07T00:01:16.641Z', '2026-10-06T05:27:44.166Z');
